<?php use Hls\Http\View as V; ?><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Referensi</th><th>Customer</th><th>Invoice</th><th>Rekening</th><th>Nominal Alokasi</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= V::escape($r['payment_date']) ?></td><td><?= V::escape($r['payment_ref']) ?></td><td><?= V::escape($r['customer_name']) ?></td><td><?= V::escape($r['official_number']) ?></td><td><?= V::escape($r['account_code']) ?></td><td><?= \Hls\Http\View::money($r['allocated']) ?></td><td><?= V::escape($r['status']) ?></td></tr><?php endforeach ?></tbody></table><?php if(!$rows): ?><p class="empty-state">Belum ada pembayaran.</p><?php endif ?></div></section>
